export interface Activity {
  id: string;
  name: string;
  description?: string;
  category: string;
  dailyGoal?: number;
  createdAt: string;
}

export interface ActivityWithStatus extends Activity {
  doneToday: boolean;
  doneCount: number;
  progressPercent: number;
}

export type DayMap = Record<string, Record<string, boolean>>;

export interface StoredData {
  version: number;
  activities: Activity[];
  dayStatus: DayMap;
  createdAt: string;
  updatedAt: string;
}

export const CURRENT_SCHEMA_VERSION = 1;

export const CATEGORIES = [
  'Gesundheit',
  'Produktivität',
  'Lernen',
  'Soziales',
  'Freizeit',
  'Sonstiges',
] as const;

export type Category = (typeof CATEGORIES)[number];

import { StoredData, CURRENT_SCHEMA_VERSION, Activity, DayMap } from '../types';

const STORAGE_KEY = 'pulseboard';

export function readStoredData(): StoredData | null {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) return null;

    const parsed = JSON.parse(raw);

    // Validate schema version
    if (typeof parsed.version !== 'number' || parsed.version > CURRENT_SCHEMA_VERSION) {
      console.warn('[storage] Unknown schema version:', parsed.version, '— resetting');
      return null;
    }

    // Basic shape validation
    if (!Array.isArray(parsed.activities)) return null;
    if (parsed.activities.some((a: unknown) => typeof a !== 'object' || !a || typeof a !== 'object')) return null;
    if (parsed.dayStatus && typeof parsed.dayStatus !== 'object') return null;

    // Ensure required fields on activities
    const validated = parsed.activities.map((a: Record<string, unknown>) => ({
      id: typeof a.id === 'string' ? a.id : crypto.randomUUID(),
      name: typeof a.name === 'string' && a.name.trim() ? a.name.trim() : 'Ohne Titel',
      description: typeof a.description === 'string' ? a.description : undefined,
      category: typeof a.category === 'string' ? a.category : 'Sonstiges',
      dailyGoal:
        typeof a.dailyGoal === 'number' && a.dailyGoal > 0
          ? a.dailyGoal
          : undefined,
      createdAt: typeof a.createdAt === 'string' ? a.createdAt : new Date().toISOString(),
    }));

    const sanitizedDayStatus: DayMap =
      parsed.dayStatus && typeof parsed.dayStatus === 'object' && !Array.isArray(parsed.dayStatus)
        ? parsed.dayStatus
        : {};

    return {
      version: CURRENT_SCHEMA_VERSION,
      activities: validated,
      dayStatus: sanitizedDayStatus,
      createdAt: typeof parsed.createdAt === 'string' ? parsed.createdAt : new Date().toISOString(),
      updatedAt: new Date().toISOString(),
    };
  } catch {
    console.warn('[storage] Failed to parse stored data — starting fresh');
    return null;
  }
}

export function writeStoredData(data: StoredData): void {
  try {
    localStorage.setItem(
      STORAGE_KEY,
      JSON.stringify({ ...data, updatedAt: new Date().toISOString() })
    );
  } catch (e) {
    if (e instanceof DOMException && e.name === 'QuotaExceededError') {
      console.error('[storage] localStorage quota exceeded');
    } else {
      console.error('[storage] Failed to save data:', e);
    }
  }
}

export function formatDateKey(date: Date): string {
  const y = date.getFullYear();
  const m = String(date.getMonth() + 1).padStart(2, '0');
  const d = String(date.getDate()).padStart(2, '0');
  return `${y}-${m}-${d}`;
}

export function parseDateKey(key: string): Date {
  const [y, m, d] = key.split('-').map(Number);
  return new Date(y, m - 1, d);
}

export function formatDisplayDate(date: Date): string {
  const today = new Date();
  const yesterday = new Date(today);
  yesterday.setDate(yesterday.getDate() - 1);
  const tomorrow = new Date(today);
  tomorrow.setDate(tomorrow.getDate() + 1);

  if (formatDateKey(date) === formatDateKey(today)) return 'Heute';
  if (formatDateKey(date) === formatDateKey(yesterday)) return 'Gestern';
  if (formatDateKey(date) === formatDateKey(tomorrow)) return 'Morgen';

  return date.toLocaleDateString('de-DE', {
    weekday: 'long',
    year: 'numeric',
    month: 'long',
    day: 'numeric',
  });
}

import { useState, useCallback, useEffect } from 'react';
import { Activity, StoredData, ActivityWithStatus } from '../types';
import { readStoredData, writeStoredData } from '../utils/storage';
import { formatDateKey } from '../utils/date';

function persist(data: StoredData): void {
  writeStoredData(data);
}

export function useActivities() {
  const [data, setData] = useState<StoredData>(() => readStoredData() || {
    version: 1,
    activities: [],
    dayStatus: {},
    createdAt: new Date().toISOString(),
    updatedAt: new Date().toISOString(),
  });

  const save = useCallback(
    (fn: (d: StoredData) => StoredData) => {
      setData((prev) => {
        const next = fn(prev);
        persist(next);
        return next;
      });
    },
    []
  );

  const addActivity = useCallback(
    (name: string, description: string | undefined, category: string, dailyGoal?: number) => {
      save((d) => {
        const activity: Activity = {
          id: crypto.randomUUID(),
          name: name.trim(),
          description: description?.trim() || undefined,
          category,
          dailyGoal,
          createdAt: new Date().toISOString(),
        };
        return { ...d, activities: [...d.activities, activity], updatedAt: new Date().toISOString() };
      });
    },
    [save]
  );

  const updateActivity = useCallback(
    (id: string, name: string, description: string | undefined, category: string, dailyGoal?: number) => {
      save((d) => ({
        ...d,
        activities: d.activities.map((a) =>
          a.id === id
            ? { ...a, name: name.trim(), description: description?.trim() || undefined, category, dailyGoal }
            : a
        ),
        updatedAt: new Date().toISOString(),
      }));
    },
    [save]
  );

  const removeActivity = useCallback(
    (id: string) => {
      save((d) => ({
        ...d,
        activities: d.activities.filter((a) => a.id !== id),
        updatedAt: new Date().toISOString(),
      }));
    },
    [save]
  );

  return {
    activities: data.activities,
    addActivity,
    updateActivity,
    removeActivity,
  };
}

export function useDayStatus(date: Date) {
  const dateKey = formatDateKey(date);

  const [data, setData] = useState<StoredData>(() => readStoredData() || {
    version: 1,
    activities: [],
    dayStatus: {},
    createdAt: '',
    updatedAt: '',
  });

  useEffect(() => {
    const fresh = readStoredData();
    if (fresh) setData(fresh);
  }, [dateKey]);

  const save = useCallback(
    (fn: (d: StoredData) => StoredData) => {
      setData((prev) => {
        const next = fn(prev);
        persist(next);
        return next;
      });
    },
    []
  );

  const toggleActivity = useCallback(
    (activityId: string) => {
      save((d) => {
        const current = d.dayStatus[dateKey] || {};
        const wasDone = current[activityId] ?? false;
        const newStatus = { ...current, [activityId]: !wasDone };

        return {
          ...d,
          dayStatus: { ...d.dayStatus, [dateKey]: newStatus },
          updatedAt: new Date().toISOString(),
        };
      });
    },
    [dateKey, save]
  );

  return {
    dayStatus: data.dayStatus,
    dateKey,
    activities: data.activities,
    toggleActivity,
  };
}

export function useActivitiesWithStatus(date: Date): ActivityWithStatus[] {
  const { dayStatus, dateKey, activities, toggleActivity } = useDayStatus(date);
  const todayKey = formatDateKey(new Date());
  const isFuture = dateKey > todayKey;

  return activities
    .map((activity) => {
      const doneToday = (dayStatus[dateKey]?.[activity.id] ?? false) && !isFuture;
      const goal = activity.dailyGoal;
      const progressPercent = goal ? Math.min(100, (doneToday ? 1 : 0) * 100) : (doneToday ? 100 : 0);
      return { ...activity, doneToday, doneCount: doneToday ? 1 : 0, progressPercent };
    })
    .sort((a, b) => a.name.localeCompare(b.name));
}

import { useState, FormEvent, useCallback } from 'react';
import { Activity } from '../types';

export interface ActivityFormProps {
  onSubmit: (name: string, description: string | undefined, category: string, dailyGoal?: number) => void;
  editing?: Activity | null;
  onCancel?: () => void;
  categories: string[];
}

export function ActivityForm({ onSubmit, editing, onCancel, categories }: ActivityFormProps) {
  const [name, setName] = useState(editing?.name ?? '');
  const [description, setDescription] = useState(editing?.description ?? '');
  const [category, setCategory] = useState(editing?.category ?? categories[0] ?? 'Sonstiges');
  const [dailyGoalStr, setDailyGoalStr] = useState(editing?.dailyGoal?.toString() ?? '');
  const [error, setError] = useState('');

  const handleSubmit = (e: FormEvent) => {
    e.preventDefault();

    if (!name.trim()) {
      setError('Bitte einen Namen eingeben');
      return;
    }

    const dailyGoal = dailyGoalStr.trim()
      ? parseInt(dailyGoalStr, 10)
      : undefined;

    if (dailyGoal && (isNaN(dailyGoal) || dailyGoal <= 0)) {
      setError('Tagesziel muss eine positive Zahl sein');
      return;
    }

    setError('');
    onSubmit(name.trim(), description?.trim() || undefined, category, dailyGoal);

    if (!editing) {
      setName('');
      setDescription('');
      setDailyGoalStr('');
    }
  };

  const handleCancel = () => {
    setName(editing?.name ?? '');
    setDescription(editing?.description ?? '');
    setCategory(editing?.category ?? categories[0] ?? 'Sonstiges');
    setDailyGoalStr(editing?.dailyGoal?.toString() ?? '');
    setError('');
    onCancel?.();
  };

  return (
    <form onSubmit={handleSubmit} className="activity-form" aria-label={editing ? 'Aktivität bearbeiten' : 'Neue Aktivität'}>
      <div className="form-group">
        <label htmlFor="activity-name">Name *</label>
        <input
          id="activity-name"
          type="text"
          value={name}
          onChange={(e) => { setName(e.target.value); if (error) setError(''); }}
          placeholder="z.B. Morgens joggen"
          required
          maxLength={100}
          aria-invalid={!!error && error.startsWith('Bitte')}
        />
      </div>

      <div className="form-group">
        <label htmlFor="activity-desc">Beschreibung</label>
        <input
          id="activity-desc"
          type="text"
          value={description}
          onChange={(e) => setDescription(e.target.value)}
          placeholder="Optional — für Details"
          maxLength={200}
        />
      </div>

      <div className="form-group">
        <label htmlFor="activity-category">Kategorie</label>
        <select
          id="activity-category"
          value={category}
          onChange={(e) => setCategory(e.target.value)}
        >
          {categories.map((cat) => (
            <option key={cat} value={cat}>{cat}</option>
          ))}
        </select>
      </div>

      <div className="form-group">
        <label htmlFor="activity-goal">Tagesziel (optional)</label>
        <input
          id="activity-goal"
          type="number"
          value={dailyGoalStr}
          onChange={(e) => setDailyGoalStr(e.target.value)}
          placeholder="z.B. 3"
          min="1"
          aria-describedby={dailyGoalStr ? 'goal-help' : undefined}
        />
        <span id="goal-help" className="form-hint">Leer lassen für einmal pro Tag</span>
      </div>

      {error && (
        <p className="form-error" role="alert">{error}</p>
      )}

      <div className="form-actions">
        <button type="submit" aria-label={editing ? 'Speichern' : 'Hinzufügen'}>
          {editing ? 'Speichern' : 'Hinzufügen'}
        </button>
        {editing && (
          <button type="button" onClick={handleCancel} className="btn-secondary">
            Abbrechen
          </button>
        )}
      </div>
    </form>
  );
}

import { Activity, ActivityWithStatus } from '../types';

export interface ActivityItemProps {
  activity: ActivityWithStatus;
  onToggle: (id: string) => void;
  onEdit: (activity: Activity) => void;
  onDelete: (id: string) => void;
}

export function ActivityItem({ activity, onToggle, onEdit, onDelete }: ActivityItemProps) {
  const handleToggle = () => {
    if (activity.dailyGoal && activity.doneCount < activity.dailyGoal) {
      // For activities with a goal, toggling increments one count
      onToggle(activity.id);
    } else {
      onToggle(activity.id);
    }
  };

  return (
    <li className="activity-item" role="listitem">
      <div className="activity-main">
        <input
          type="checkbox"
          id={`toggle-${activity.id}`}
          checked={activity.doneToday}
          onChange={handleToggle}
          aria-label={`${activity.name} ${activity.doneToday ? '— erledigt' : '— offen'}`}
          className="activity-checkbox"
          disabled={false}
        />
        <label htmlFor={`toggle-${activity.id}`} className="activity-label">
          <span className={`activity-name ${activity.doneToday ? 'done' : ''}`}>
            {activity.name}
          </span>
          {activity.description && (
            <span className="activity-desc">{activity.description}</span>
          )}
        </label>
      </div>

      <div className="activity-meta">
        <span className="activity-category" aria-label={`Kategorie: ${activity.category}`}>
          {activity.category}
        </span>
        {activity.dailyGoal && (
          <span className="activity-goal" aria-label={`Tagesziel: ${activity.dailyGoal}`}>
            {activity.doneCount}/{activity.dailyGoal}
          </span>
        )}
        <span className="activity-progress">
          {activity.progressPercent}%
        </span>
      </div>

      <div className="activity-actions">
        <button
          type="button"
          onClick={() => onEdit(activity)}
          aria-label={`${activity.name} bearbeiten`}
          className="btn-icon"
          title="Bearbeiten"
        >
          ✎
        </button>
        <button
          type="button"
          onClick={() => onDelete(activity.id)}
          aria-label={`${activity.name} löschen`}
          className="btn-icon"
          title="Löschen"
        >
          ✕
        </button>
      </div>
    </li>
  );
}

import { Activity, ActivityWithStatus } from '../types';
import { ActivityItem } from './ActivityItem';
import { ActivityForm } from './ActivityForm';

export interface ActivityListProps {
  activities: ActivityWithStatus[];
  onToggle: (id: string) => void;
  onEdit: (activity: Activity) => void;
  onDelete: (id: string) => void;
  categories: string[];
  onAdd: (name: string, description: string | undefined, category: string, dailyGoal?: number) => void;
  isFuture: boolean;
}

export function ActivityList({
  activities,
  onToggle,
  onEdit,
  onDelete,
  categories,
  onAdd,
  isFuture,
}: ActivityListProps) {
  const [editing, setEditing] = useState<Activity | null>(null);

  const handleCancelEdit = () => setEditing(null);
  const handleEdit = (activity: Activity) => setEditing(activity);
  const handleDelete = (id: string) => {
    if (window.confirm('Aktivität wirklich löschen?')) {
      onDelete(id);
    }
  };
  const handleFormSubmit = (
    name: string,
    description: string | undefined,
    category: string,
    dailyGoal?: number
  ) => {
    if (editing) {
      onEdit(editing.id, name, description, category, dailyGoal);
    } else {
      onAdd(name, description, category, dailyGoal);
    }
    setEditing(null);
  };

  const grouped = activities.reduce<Record<string, ActivityWithStatus[]>>((acc, a) => {
    (acc[a.category] = acc[a.category] || []).push(a);
    return acc;
  }, {});

  if (activities.length === 0 && !editing) {
    return (
      <div className="empty-state">
        <p>Noch keine Aktivitäten vorhanden.</p>
        <p>Füge deine erste Gewohnheit oder Aufgabe hinzu.</p>
      </div>
    );
  }

  if (editing && !isFuture) {
    return (
      <section aria-label="Aktivität bearbeiten">
        <ActivityForm
          onSubmit={handleFormSubmit}
          editing={editing}
          onCancel={handleCancelEdit}
          categories={categories}
        />
      </section>
    );
  }

  return (
    <>
      {!editing && (
        <section aria-label="Neue Aktivität">
          <ActivityForm
            onSubmit={handleFormSubmit}
            categories={categories}
          />
        </section>
      )}

      {isFuture && (
        <p className="future-note">
          ⚠ Zukünftige Tage — Abhaken ist nicht möglich.
        </p>
      )}

      {Object.entries(grouped).map(([category, items]) => (
        <section key={category} aria-label={`Kategorie ${category}`}>
          <h3 className="category-heading">{category}</h3>
          <ul role="list">
            {items.map((a) => (
              <ActivityItem
                key={a.id}
                activity={a}
                onToggle={onToggle}
                onEdit={handleEdit}
                onDelete={handleDelete}
              />
            ))}
          </ul>
        </section>
      ))}
    </>
  );
}

import { formatDisplayDate } from '../utils/date';
import { ActivityWithStatus } from '../types';

export interface DashboardProps {
  activities: ActivityWithStatus[];
  date: Date;
}

export function Dashboard({ activities, date }: DashboardProps) {
  const doneCount = activities.filter((a) => a.doneToday).length;
  const totalCount = activities.length;
  const openCount = totalCount - doneCount;
  const progressPercent = totalCount > 0 ? Math.round((doneCount / totalCount) * 100) : 0;

  return (
    <section aria-label="Tagesübersicht" className="dashboard">
      <time className="dashboard-date" dateTime={date.toISOString()}>
        {formatDisplayDate(date)}
      </time>

      <div className="stats-grid">
        <div className="stat-card">
          <span className="stat-value">{doneCount}</span>
          <span className="stat-label">Erledigt</span>
        </div>
        <div className="stat-card">
          <span className="stat-value">{openCount}</span>
          <span className="stat-label">Offen</span>
        </div>
      </div>

      <div className="progress-bar" role="progressbar" aria-valuenow={progressPercent} aria-valuemin={0} aria-valuemax={100}>
        <div
          className="progress-fill"
          style={{ width: `${progressPercent}%` }}
        />
      </div>
      <span className="progress-label">{progressPercent}% abgeschlossen</span>

      <div className="category-overview">
        {activities
          .reduce<Record<string, { total: number; done: number }>>((acc, a) => {
            const existing = acc[a.category] || { total: 0, done: 0 };
            acc[a.category] = {
              total: existing.total + 1,
              done: existing.done + (a.doneToday ? 1 : 0),
            };
            return acc;
          }, {})
          .sort((a, b) => b.total - a.total)
          .map(({ total, done }) => (
            <div key={`${done}-${total}`} className="mini-stat">
              <span>{done}/{total}</span>
            </div>
          ))}
      </div>
    </section>
  );
}

import { formatDateKey, formatDisplayDate } from '../utils/date';

export interface DayNavigationProps {
  currentDate: Date;
  onPrev: () => void;
  onNext: () => void;
  onToday: () => void;
  maxDate?: Date;
}

export function DayNavigation({ currentDate, onPrev, onNext, onToday, maxDate }: DayNavigationProps) {
  const todayKey = formatDateKey(new Date());
  const currentKey = formatDateKey(currentDate);
  const isMax = maxDate ? formatDateKey(currentDate) === formatDateKey(maxDate) : false;
  const isPast = currentKey < todayKey;
  const isFuture = currentKey > todayKey;

  return (
    <nav className="day-nav" aria-label="Tagesnavigation">
      <div className="nav-controls">
        <button
          type="button"
          onClick={onPrev}
          aria-label="Vorheriger Tag"
          title="Vorheriger Tag"
        >
          ←
        </button>

        <span className="nav-date" aria-live="polite">
          {formatDisplayDate(currentDate)}
          {(isFuture || (isMax && currentKey > todayKey)) && ' (Zukunft)'}
        </span>

        <button
          type="button"
          onClick={onNext}
          disabled={isMax}
          aria-label="Nächster Tag"
          title={isMax ? 'Maximales Datum erreicht' : 'Nächster Tag'}
        >
          →
        </button>
      </div>

      {!isPast && (
        <button
          type="button"
          onClick={onToday}
          className="btn-secondary"
        >
          Zu heute wechseln
        </button>
      )}
    </nav>
  );
}

export function EmptyState({ message = 'Noch keine Daten vorhanden.', sub = 'Füge deine erste Aktivität hinzu.' }: { message?: string; sub?: string }) {
  return (
    <div className="empty-state">
      <p>{message}</p>
      <p>{sub}</p>
    </div>
  );
}

import { useState, useCallback } from 'react';
import { useActivities, useActivitiesWithStatus } from '../hooks/useActivities';
import { Activity } from '../types';
import { formatDateKey } from '../utils/date';
import { ActivityList } from './ActivityList';
import { Dashboard } from './Dashboard';
import { DayNavigation } from './DayNavigation';
import { EmptyState } from './EmptyState';

export const CATEGORIES = [
  'Gesundheit',
  'Produktivität',
  'Lernen',
  'Soziales',
  'Freizeit',
  'Sonstiges',
] as const;

export function App() {
  const today = new Date();
  const [currentDate, setCurrentDate] = useState<Date>(() => {
    const stored = localStorage.getItem('pulseboard-current-date');
    if (stored) {
      const parsed = new Date(stored);
      if (!isNaN(parsed.getTime())) return parsed;
    }
    return today;
  });
  const [maxFutureDate] = useState<Date>(() => {
    const d = new Date(today);
    d.setDate(d.getDate() + 7);
    return d;
  });

  const saveDate = useCallback((d: Date) => {
    localStorage.setItem('pulseboard-current-date', d.toISOString());
    setCurrentDate(d);
  }, []);

  const goPrev = useCallback(() => {
    const d = new Date(currentDate);
    d.setDate(d.getDate() - 1);
    if (d <= maxFutureDate) saveDate(d);
  }, [currentDate, maxFutureDate, saveDate]);

  const goNext = useCallback(() => {
    const d = new Date(currentDate);
    d.setDate(d.getDate() + 1);
    if (d <= maxFutureDate) saveDate(d);
  }, [currentDate, maxFutureDate, saveDate]);

  const goToday = useCallback(() => saveDate(today), [saveDate, today]);

  const { activities, addActivity, updateActivity, removeActivity } = useActivities();
  const statusActivities = useActivitiesWithStatus(currentDate);
  const todayKey = formatDateKey(today);
  const isFuture = formatDateKey(currentDate) > todayKey;

  const handleToggle = (id: string) => {
    // Implemented in useActivitiesWithStatus, but we need the dayStatus hook for this
    // For simplicity, we'll dispatch via a custom event
    window.dispatchEvent(new CustomEvent('pulseboard-toggle', { detail: { activityId: id } }));
  };

  const handleEdit = (id: string, name: string, description: string | undefined, category: string, dailyGoal?: number) => {
    updateActivity(id, name, description, category, dailyGoal);
  };

  const handleDelete = (id: string) => {
    removeActivity(id);
  };

  return (
    <div className="app">
      <header className="app-header">
        <h1>PulseBoard</h1>
        <p>Täglicher Begleiter</p>
      </header>

      <main className="app-main">
        <Dashboard activities={statusActivities} date={currentDate} />

        <DayNavigation
          currentDate={currentDate}
          onPrev={goPrev}
          onNext={goNext}
          onToday={goToday}
          maxDate={maxFutureDate}
        />

        {activities.length === 0 ? (
          <EmptyState
            message="Dein PulseBoard ist leer."
            sub="Füge deine erste Aktivität oder Gewohnheit hinzu."
          />
        ) : (
          <ActivityList
            activities={statusActivities}
            onToggle={handleToggle}
            onEdit={handleEdit}
            onDelete={handleDelete}
            categories={CATEGORIES}
            onAdd={addActivity}
            isFuture={isFuture}
          />
        )}
      </main>
    </div>
  );
}

import { StrictMode } from 'react';
import { createRoot } from 'react-dom/client';
import { App } from './components/App';
import './styles/globals.css';

