@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&display=swap');

:root {
  /* Light mode — default */
  --bg: #FAFAF9;
  --bg-card: #FFFFFF;
  --bg-input: #FFFFFF;
  --text: #1A1A1A;
  --text-muted: #6B7280;
  --text-placeholder: #9CA3AF;
  --accent: #4F46E5;
  --accent-hover: #4338CA;
  --accent-light: rgba(79, 70, 229, 0.08);
  --border: #E5E7EB;
  --border-focus: #4F46E5;
  --success: #059669;
  --success-bg: rgba(5, 150, 105, 0.08);
  --error: #DC2626;
  --error-bg: rgba(220, 38, 38, 0.08);
  --future-notice: #D97706;
  --future-bg: rgba(217, 119, 6, 0.08);
  --shadow: rgba(0, 0, 0, 0.06);
  --radius: 10px;
  --radius-sm: 6px;
}

@media (prefers-color-scheme: dark) {
  :root {
    --bg: #0F0F11;
    --bg-card: #1A1A1E;
    --bg-input: #232329;
    --text: #EAEAEA;
    --text-muted: #9CA3AF;
    --text-placeholder: #6B7280;
    --accent: #818CF8;
    --accent-hover: #6366F1;
    --accent-light: rgba(129, 140, 248, 0.12);
    --border: #2D2D35;
    --border-focus: #818CF8;
    --success: #34D399;
    --success-bg: rgba(52, 211, 153, 0.1);
    --error: #F87171;
    --error-bg: rgba(248, 113, 113, 0.1);
    --future-notice: #FBBF24;
    --future-bg: rgba(251, 191, 36, 0.1);
    --shadow: rgba(0, 0, 0, 0.2);
  }
}

/* Reset & base */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: 'Inter', system-ui, -apple-system, sans-serif;
  background: var(--bg);
  color: var(--text);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  min-height: 100vh;
}

/* App shell */
.app {
  max-width: 560px;
  margin: 0 auto;
  padding: 0 16px 48px;
}

/* Header */
.app-header {
  padding: 32px 0 8px;
}

.app-header h1 {
  font-size: 1.75rem;
  font-weight: 700;
  letter-spacing: -0.02em;
  color: var(--text);
}

.app-header p {
  font-size: 0.875rem;
  color: var(--text-muted);
  margin-top: 2px;
}

/* Main */
.app-main {
  margin-top: 24px;
  display: flex;
  flex-direction: column;
  gap: 24px;
}

/* Dashboard */
.dashboard {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 20px;
  box-shadow: 0 1px 3px var(--shadow);
}

.dashboard-date {
  font-size: 0.8rem;
  color: var(--text-muted);
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.stats-grid {
  display: flex;
  gap: 16px;
  margin-top: 12px;
}

.stat-card {
  flex: 1;
  background: var(--accent-light);
  border-radius: var(--radius-sm);
  padding: 12px 16px;
  text-align: center;
}

.stat-value {
  display: block;
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--accent);
}

.stat-label {
  font-size: 0.75rem;
  color: var(--text-muted);
}

.progress-bar {
  margin-top: 16px;
  height: 6px;
  background: var(--border);
  border-radius: 3px;
  overflow: hidden;
}

.progress-fill {
  height: 100%;
  background: var(--accent);
  border-radius: 3px;
  transition: width 0.2s ease;
}

.progress-label {
  display: block;
  font-size: 0.75rem;
  color: var(--text-muted);
  margin-top: 4px;
}

.category-overview {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 12px;
}

.mini-stat {
  background: var(--bg);
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  padding: 4px 10px;
  font-size: 0.75rem;
  font-weight: 500;
  color: var(--text-muted);
}

/* Day navigation */
.day-nav {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.nav-controls {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
}

.nav-controls button {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  width: 36px;
  height: 36px;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  font-size: 1rem;
  color: var(--text);
  transition: background 0.1s, border-color 0.1s;
}

.nav-controls button:hover:not(:disabled) {
  background: var(--accent-light);
  border-color: var(--accent);
}

.nav-controls button:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

.nav-date {
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--text);
  text-align: center;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  max-width: 200px;
}

/* Forms */
.activity-form {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 16px;
  display: flex;
  flex-direction: column;
  gap: 12px;
  box-shadow: 0 1px 3px var(--shadow);
}

.form-group label {
  display: block;
  font-size: 0.75rem;
  font-weight: 500;
  color: var(--text-muted);
  margin-bottom: 4px;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.form-group input,
.form-group select {
  width: 100%;
  padding: 8px 12px;
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  background: var(--bg-input);
  color: var(--text);
  font-size: 0.875rem;
  font-family: inherit;
  transition: border-color 0.15s;
}

.form-group input:focus,
.form-group select:focus {
  outline: none;
  border-color: var(--border-focus);
  box-shadow: 0 0 0 2px var(--accent-light);
}

.form-group input::placeholder {
  color: var(--text-placeholder);
}

.form-hint {
  font-size: 0.7rem;
  color: var(--text-muted);
}

.form-error {
  color: var(--error);
  font-size: 0.8rem;
  background: var(--error-bg);
  padding: 8px 12px;
  border-radius: var(--radius-sm);
  margin: 0;
}

.form-actions {
  display: flex;
  gap: 8px;
  justify-content: flex-end;
}

/* Buttons */
button {
  font-family: inherit;
  font-size: 0.8125rem;
  font-weight: 500;
  cursor: pointer;
  padding: 8px 16px;
  border-radius: var(--radius-sm);
  border: 1px solid var(--border);
  background: var(--accent);
  color: white;
  transition: background 0.1s;
}

button:hover {
  background: var(--accent-hover);
}

button:active {
  transform: scale(0.98);
}

.btn-secondary {
  background: transparent;
  color: var(--text-muted);
  border-color: var(--border);
}

.btn-secondary:hover {
  background: var(--accent-light);
  color: var(--text);
  border-color: var(--accent);
}

.btn-icon {
  width: 28px;
  height: 28px;
  padding: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  background: transparent;
  color: var(--text-muted);
  border: none;
  font-size: 0.75rem;
}

.btn-icon:hover {
  background: var(--error-bg);
  color: var(--error);
}

/* Activity list */
.activity-item {
  display: flex;
  align-items: center;
  padding: 10px 0;
  border-bottom: 1px solid var(--border);
  gap: 10px;
}

.activity-item:last-child {
  border-bottom: none;
}

.activity-main {
  display: flex;
  align-items: center;
  gap: 8px;
  flex: 1;
  min-width: 0;
}

.activity-checkbox {
  width: 18px;
  height: 18px;
  accent-color: var(--accent);
  cursor: pointer;
  flex-shrink: 0;
}

.activity-label {
  cursor: pointer;
  display: flex;
  flex-direction: column;
  min-width: 0;
}

.activity-name {
  font-size: 0.9375rem;
  font-weight: 500;
  transition: color 0.15s;
}

.activity-name.done {
  text-decoration: line-through;
  color: var(--success);
}

.activity-desc {
  font-size: 0.75rem;
  color: var(--text-muted);
}

.activity-meta {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-shrink: 0;
}

.activity-category {
  font-size: 0.6875rem;
  color: var(--text-muted);
  background: var(--accent-light);
  padding: 2px 6px;
  border-radius: 4px;
  white-space: nowrap;
}

.activity-goal {
  font-size: 0.6875rem;
  color: var(--text-muted);
  white-space: nowrap;
}

.activity-progress {
  font-size: 0.75rem;
  font-weight: 600;
  color: var(--success);
  min-width: 36px;
  text-align: right;
}

.activity-actions {
  display: flex;
  gap: 4px;
  opacity: 0.5;
  transition: opacity 0.1s;
}

.activity-item:hover .activity-actions {
  opacity: 1;
}

.category-heading {
  font-size: 0.8125rem;
  font-weight: 600;
  color: var(--text-muted);
  padding: 8px 0 4px;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.future-note {
  background: var(--future-bg);
  color: var(--future-notice);
  padding: 8px 12px;
  border-radius: var(--radius-sm);
  font-size: 0.8125rem;
  margin: 0;
}

/* Empty state */
.empty-state {
  text-align: center;
  padding: 32px 16px;
  color: var(--text-muted);
}

.empty-state p:first-child {
  font-size: 0.9375rem;
  font-weight: 500;
  color: var(--text);
}

.empty-state p:last-child {
  font-size: 0.8125rem;
  margin-top: 4px;
}

/* Focus styles for accessibility */
*:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

/* Reduced motion */
@media (prefers-reduced-motion: reduce) {
  .progress-fill {
    transition: none;
  }
  button:active {
    transform: none;
  }
}

/* Mobile */
@media (max-width: 480px) {
  .app {
    padding: 0 12px 32px;
  }

  .app-header {
    padding: 24px 0 4px;
  }

  .app-header h1 {
    font-size: 1.5rem;
  }

  .stats-grid {
    flex-direction: column;
  }

  .nav-date {
    max-width: 140px;
  }

  .activity-meta {
    gap: 4px;
  }

  .activity-category {
    display: none;
  }
}

