import { useState, FormEvent, useCallback } from 'react';
import { Activity } from '../types';

export interface ActivityFormProps {
  onSubmit: (name: string, description: string | undefined, category: string, dailyGoal?: number) => void;
  editing?: Activity | null;
  onCancel?: () => void;
  categories: string[];
}

export function ActivityForm({ onSubmit, editing, onCancel, categories }: ActivityFormProps) {
  const [name, setName] = useState(editing?.name ?? '');
  const [description, setDescription] = useState(editing?.description ?? '');
  const [category, setCategory] = useState(editing?.category ?? (categories[0] ?? 'Sonstiges'));
  const [dailyGoalStr, setDailyGoalStr] = useState(editing?.dailyGoal?.toString() ?? '');
  const [error, setError] = useState('');

  const handleSubmit = (e: FormEvent) => {
    e.preventDefault();
    setError('');

    if (!name.trim()) {
      setError('Bitte einen Namen eingeben');
      return;
    }

    const dailyGoal = dailyGoalStr.trim()
      ? parseInt(dailyGoalStr, 10)
      : undefined;

    if (dailyGoal && (isNaN(dailyGoal) || dailyGoal <= 0)) {
      setError('Tagesziel muss eine positive Zahl sein');
      return;
    }

    onSubmit(name.trim(), description?.trim() || undefined, category, dailyGoal);

    if (!editing) {
      setName('');
      setDescription('');
      setDailyGoalStr('');
    }
  };

  const handleCancel = () => {
    setName(editing?.name ?? '');
    setDescription(editing?.description ?? '');
    setCategory(editing?.category ?? (categories[0] ?? 'Sonstiges'));
    setDailyGoalStr(editing?.dailyGoal?.toString() ?? '');
    setError('');
    onCancel?.();
  };

  return (
    <form onSubmit={handleSubmit} className="activity-form" aria-label={editing ? 'Aktivität bearbeiten' : 'Neue Aktivität'}>
      <div className="form-group">
        <label htmlFor="activity-name">Name *</label>
        <input
          id="activity-name"
          type="text"
          value={name}
          onChange={(e) => { setName(e.target.value); if (error) setError(''); }}
          placeholder="z.B. Morgens joggen"
          required
          maxLength={100}
          aria-invalid={!!error && error.startsWith('Bitte')}
        />
      </div>

      <div className="form-group">
        <label htmlFor="activity-desc">Beschreibung</label>
        <input
          id="activity-desc"
          type="text"
          value={description}
          onChange={(e) => setDescription(e.target.value)}
          placeholder="Optional — für Details"
          maxLength={200}
        />
      </div>

      <div className="form-group">
        <label htmlFor="activity-category">Kategorie</label>
        <select
          id="activity-category"
          value={category}
          onChange={(e) => setCategory(e.target.value)}
        >
          {categories.map((cat) => (
            <option key={cat} value={cat}>{cat}</option>
          ))}
        </select>
      </div>

      <div className="form-group">
        <label htmlFor="activity-goal">Tagesziel (optional)</label>
        <input
          id="activity-goal"
          type="number"
          value={dailyGoalStr}
          onChange={(e) => setDailyGoalStr(e.target.value)}
          placeholder="z.B. 3"
          min="1"
          aria-describedby={dailyGoalStr ? 'goal-help' : undefined}
        />
        <span id="goal-help" className="form-hint">Leer lassen für einmal pro Tag</span>
      </div>

      {error ? (
        <p className="form-error" role="alert">{error}</p>
      ) : null}

      <div className="form-actions">
        <button type="submit" aria-label={editing ? 'Speichern' : 'Hinzufügen'}>
          {editing ? 'Speichern' : 'Hinzufügen'}
        </button>
        {editing && (
          <button type="button" onClick={handleCancel} className="btn-secondary">
            Abbrechen
          </button>
        )}
      </div>
    </form>
  );
}

import { describe, it, expect, beforeEach, vi } from 'vitest';
import { render, screen, fireEvent, waitFor } from '@testing-library/react';
import { ActivityForm } from '../../src/components/ActivityForm';
import { Activity } from '../../src/types';

vi.stubGlobal('crypto', {
  randomUUID: () => 'test-uuid-' + Math.random().toString(36).slice(2),
});

const CATEGORIES = ['Gesundheit', 'Produktivität', 'Lernen', 'Soziales', 'Freizeit', 'Sonstiges'];

describe('ActivityForm', () => {
  let onSubmit = vi.fn();
  let onCancel = vi.fn();

  beforeEach(() => {
    onSubmit = vi.fn();
    onCancel = vi.fn();
  });

  it('renders form fields', () => {
    render(<ActivityForm onSubmit={onSubmit} categories={CATEGORIES} />);
    expect(screen.getByLabelText(/name/i)).toBeInTheDocument();
    expect(screen.getByLabelText(/beschreibung/i)).toBeInTheDocument();
    expect(screen.getByLabelText(/kategorie/i)).toBeInTheDocument();
    expect(screen.getByLabelText(/tagesziel/i)).toBeInTheDocument();
  });

  it('submits with valid data', () => {
    render(<ActivityForm onSubmit={onSubmit} categories={CATEGORIES} />);

    fireEvent.change(screen.getByLabelText(/name/i), { target: { value: 'Joggen' } });
    fireEvent.change(screen.getByLabelText(/beschreibung/i), { target: { value: 'Morgens um 7' } });
    fireEvent.change(screen.getByLabelText(/kategorie/i), { target: { value: 'Gesundheit' } });
    fireEvent.change(screen.getByLabelText(/tagesziel/i), { target: { value: '3' } });

    fireEvent.click(screen.getByRole('button', { name: 'Hinzufügen' }));

    expect(onSubmit).toHaveBeenCalledWith('Joggen', 'Morgens um 7', 'Gesundheit', 3);
  });

  it('submits without optional fields', () => {
    render(<ActivityForm onSubmit={onSubmit} categories={CATEGORIES} />);

    fireEvent.change(screen.getByLabelText(/name/i), { target: { value: 'Lesen' } });
    fireEvent.click(screen.getByRole('button', { name: 'Hinzufügen' }));

    // Default category is the first in the array ('Gesundheit')
    expect(onSubmit).toHaveBeenCalledWith('Lesen', undefined, 'Gesundheit', undefined);
  });

  it('shows error for empty name', async () => {
    render(<ActivityForm onSubmit={onSubmit} categories={CATEGORIES} />);

    fireEvent.click(screen.getByRole('button', { name: 'Hinzufügen' }));

    expect(screen.getByRole('alert')).toHaveTextContent('Bitte einen Namen eingeben');
    expect(onSubmit).not.toHaveBeenCalled();
  });

  it('shows error for invalid daily goal', async () => {
    render(<ActivityForm onSubmit={onSubmit} categories={CATEGORIES} />);

    fireEvent.change(screen.getByLabelText(/name/i), { target: { value: 'Test' } });
    fireEvent.change(screen.getByLabelText(/tagesziel/i), { target: { value: '-5' } });
    fireEvent.click(screen.getByRole('button', { name: 'Hinzufügen' }));

    expect(screen.getByRole('alert')).toHaveTextContent('Tagesziel muss eine positive Zahl sein');
    expect(onSubmit).not.toHaveBeenCalled();
  });

  it('renders with editing data', () => {
    const editing: Activity = {
      id: 'edit-1',
      name: 'Editierbare Aktivität',
      category: 'Produktivität',
      description: 'Eine Beschreibung',
      createdAt: '2025-01-01T00:00:00Z',
    };

    render(
      <ActivityForm
        onSubmit={onSubmit}
        editing={editing}
        onCancel={onCancel}
        categories={CATEGORIES}
      />
    );

    expect(screen.getByLabelText(/name/i)).toHaveValue('Editierbare Aktivität');
    expect(screen.getByLabelText(/beschreibung/i)).toHaveValue('Eine Beschreibung');
    expect(screen.getByLabelText(/kategorie/i)).toHaveValue('Produktivität');
  });

  it('cancels editing when cancel button clicked', () => {
    const editing: Activity = {
      id: 'edit-2',
      name: 'Editierbare Aktivität',
      category: 'Produktivität',
      createdAt: '2025-01-01T00:00:00Z',
    };

    render(
      <ActivityForm
        onSubmit={onSubmit}
        editing={editing}
        onCancel={onCancel}
        categories={CATEGORIES}
      />
    );

    fireEvent.click(screen.getByRole('button', { name: 'Abbrechen' }));
    expect(onCancel).toHaveBeenCalled();
  });
});

