import { useState, useEffect, FormEvent } from 'react';
import { Activity } from '../types';

export interface ActivityFormProps {
  onSubmit: (name: string, description: string | undefined, category: string, dailyGoal?: number) => void;
  editing?: Activity | null;
  onCancel?: () => void;
  categories: string[];
}

export function ActivityForm({ onSubmit, editing, onCancel, categories }: ActivityFormProps) {
  const [name, setName] = useState(editing?.name ?? '');
  const [description, setDescription] = useState(editing?.description ?? '');
  const [category, setCategory] = useState(editing?.category ?? (categories[0] ?? 'Sonstiges'));
  const [dailyGoalStr, setDailyGoalStr] = useState(editing?.dailyGoal?.toString() ?? '');
  const [error, setError] = useState('');

  // Sync form state when editing prop changes (entering edit mode)
  useEffect(() => {
    if (editing) {
      setName(editing.name);
      setDescription(editing.description ?? '');
      setCategory(editing.category);
      setDailyGoalStr(editing.dailyGoal?.toString() ?? '');
      setError('');
    }
  }, [editing]);

  const handleSubmit = (e: FormEvent) => {
    e.preventDefault();
    setError('');

    if (!name.trim()) {
      setError('Bitte einen Namen eingeben');
      return;
    }

    const dailyGoal = dailyGoalStr.trim()
      ? parseInt(dailyGoalStr, 10)
      : undefined;

    if (dailyGoal && (isNaN(dailyGoal) || dailyGoal <= 0)) {
      setError('Tagesziel muss eine positive Zahl sein');
      return;
    }

    onSubmit(name.trim(), description?.trim() || undefined, category, dailyGoal);

    if (!editing) {
      setName('');
      setDescription('');
      setDailyGoalStr('');
    }
  };

  const handleCancel = () => {
    if (editing) {
      setName(editing.name);
      setDescription(editing.description ?? '');
      setCategory(editing.category);
      setDailyGoalStr(editing.dailyGoal?.toString() ?? '');
    } else {
      setName('');
      setDescription('');
      setDailyGoalStr('');
    }
    setError('');
    onCancel?.();
  };

  return (
    <form onSubmit={handleSubmit} className="activity-form" aria-label={editing ? 'Aktivität bearbeiten' : 'Neue Aktivität'} noValidate>
      <div className="form-group">
        <label htmlFor="activity-name">Name *</label>
        <input
          id="activity-name"
          type="text"
          value={name}
          onChange={(e) => { setName(e.target.value); if (error) setError(''); }}
          placeholder="z.B. Morgens joggen"
          data-testid="name-input"
          maxLength={100}
        />
      </div>

      <div className="form-group">
        <label htmlFor="activity-desc">Beschreibung</label>
        <input
          id="activity-desc"
          type="text"
          value={description}
          onChange={(e) => setDescription(e.target.value)}
          placeholder="Optional — für Details"
          maxLength={200}
        />
      </div>

      <div className="form-group">
        <label htmlFor="activity-category">Kategorie</label>
        <select
          id="activity-category"
          value={category}
          onChange={(e) => setCategory(e.target.value)}
        >
          {categories.map((cat) => (
            <option key={cat} value={cat}>{cat}</option>
          ))}
        </select>
      </div>

      <div className="form-group">
        <label htmlFor="activity-goal">Tagesziel (optional)</label>
        <input
          id="activity-goal"
          type="number"
          value={dailyGoalStr}
          onChange={(e) => setDailyGoalStr(e.target.value)}
          placeholder="z.B. 3"
          min="1"
          aria-describedby={dailyGoalStr ? 'goal-help' : undefined}
        />
        <span id="goal-help" className="form-hint">Leer lassen für einmal pro Tag</span>
      </div>

      {error ? (
        <p className="form-error" role="alert">{error}</p>
      ) : null}

      <div className="form-actions">
        <button type="submit" aria-label={editing ? 'Speichern' : 'Hinzufügen'}>
          {editing ? 'Speichern' : 'Hinzufügen'}
        </button>
        {editing && (
          <button type="button" onClick={handleCancel} className="btn-secondary">
            Abbrechen
          </button>
        )}
      </div>
    </form>
  );
}

import { Activity, ActivityWithStatus } from '../types';
import { ActivityItem } from './ActivityItem';
import { ActivityForm } from './ActivityForm';

export interface ActivityListProps {
  activities: ActivityWithStatus[];
  onToggle: (id: string) => void;
  onEdit: (id: string, name: string, description: string | undefined, category: string, dailyGoal?: number) => void;
  onDelete: (id: string) => void;
  categories: readonly string[];
  onAdd: (name: string, description: string | undefined, category: string, dailyGoal?: number) => void;
  isFuture: boolean;
}

export function ActivityList({
  activities,
  onToggle,
  onEdit,
  onDelete,
  categories,
  onAdd,
  isFuture,
}: ActivityListProps) {
  const [editing, setEditing] = useState<Activity | null>(null);

  const handleCancelEdit = () => setEditing(null);
  const handleEdit = (activity: Activity) => setEditing(activity);
  const handleDelete = (id: string) => {
    if (window.confirm('Aktivität wirklich löschen?')) {
      onDelete(id);
    }
  };
  const handleFormSubmit = (
    name: string,
    description: string | undefined,
    category: string,
    dailyGoal?: number
  ) => {
    if (editing) {
      onEdit(editing.id, name, description, category, dailyGoal);
    } else {
      onAdd(name, description, category, dailyGoal);
    }
    setEditing(null);
  };

  const grouped = activities.reduce<Record<string, ActivityWithStatus[]>>((acc, a) => {
    (acc[a.category] = acc[a.category] || []).push(a);
    return acc;
  }, {});

  if (activities.length === 0 && !editing) {
    return (
      <div className="empty-state">
        <p>Noch keine Aktivitäten vorhanden.</p>
        <p>Füge deine erste Gewohnheit oder Aufgabe hinzu.</p>
      </div>
    );
  }

  if (editing && !isFuture) {
    return (
      <section aria-label="Aktivität bearbeiten">
        <ActivityForm
          onSubmit={handleFormSubmit}
          editing={editing}
          onCancel={handleCancelEdit}
          categories={categories}
        />
      </section>
    );
  }

  return (
    <>
      {!editing && (
        <section aria-label="Neue Aktivität">
          <ActivityForm
            onSubmit={handleFormSubmit}
            categories={categories}
          />
        </section>
      )}

      {isFuture && (
        <p className="future-note">
          ⚠ Zukünftige Tage — Abhaken ist nicht möglich.
        </p>
      )}

      {Object.entries(grouped).map(([category, items]) => (
        <section key={category} aria-label={`Kategorie ${category}`}>
          <h3 className="category-heading">{category}</h3>
          <ul role="list">
            {items.map((a) => (
              <ActivityItem
                key={a.id}
                activity={a}
                onToggle={onToggle}
                onEdit={handleEdit}
                onDelete={handleDelete}
              />
            ))}
          </ul>
        </section>
      ))}
    </>
  );
}

import { useState, useCallback, useEffect } from 'react';
import { useActivities, useActivitiesWithStatus } from '../hooks/useActivities';
import { formatDateKey } from '../utils/date';
import { ActivityList } from './ActivityList';
import { Dashboard } from './Dashboard';
import { DayNavigation } from './DayNavigation';
import { EmptyState } from './EmptyState';

export const CATEGORIES = [
  'Gesundheit',
  'Produktivität',
  'Lernen',
  'Soziales',
  'Freizeit',
  'Sonstiges',
] as const;

export function App() {
  const today = new Date();
  const [currentDate, setCurrentDate] = useState<Date>(() => {
    const stored = localStorage.getItem('pulseboard-current-date');
    if (stored) {
      const parsed = new Date(stored);
      if (!isNaN(parsed.getTime())) return parsed;
    }
    return today;
  });
  const [maxFutureDate] = useState<Date>(() => {
    const d = new Date(today);
    d.setDate(d.getDate() + 7);
    return d;
  });

  const saveDate = useCallback((d: Date) => {
    localStorage.setItem('pulseboard-current-date', d.toISOString());
    setCurrentDate(d);
  }, []);

  const goPrev = useCallback(() => {
    const d = new Date(currentDate);
    d.setDate(d.getDate() - 1);
    if (d <= maxFutureDate) saveDate(d);
  }, [currentDate, maxFutureDate, saveDate]);

  const goNext = useCallback(() => {
    const d = new Date(currentDate);
    d.setDate(d.getDate() + 1);
    if (d <= maxFutureDate) saveDate(d);
  }, [currentDate, maxFutureDate, saveDate]);

  const goToday = useCallback(() => saveDate(today), [saveDate, today]);

  const { activities, addActivity, updateActivity, removeActivity } = useActivities();
  const statusActivities = useActivitiesWithStatus(currentDate);
  const todayKey = formatDateKey(today);
  const isFuture = formatDateKey(currentDate) > todayKey;

  const handleToggle = (id: string) => {
    window.dispatchEvent(new CustomEvent('pulseboard-toggle', { detail: { activityId: id } }));
  };

  const handleEdit = (id: string, name: string, description: string | undefined, category: string, dailyGoal?: number) => {
    updateActivity(id, name, description, category, dailyGoal);
  };

  const handleDelete = (id: string) => {
    removeActivity(id);
  };

  return (
    <div className="app">
      <header className="app-header">
        <h1>PulseBoard</h1>
        <p>Täglicher Begleiter</p>
      </header>

      <main className="app-main">
        <Dashboard activities={statusActivities} date={currentDate} />

        <DayNavigation
          currentDate={currentDate}
          onPrev={goPrev}
          onNext={goNext}
          onToday={goToday}
          maxDate={maxFutureDate}
        />

        {activities.length === 0 ? (
          <EmptyState
            message="Dein PulseBoard ist leer."
            sub="Füge deine erste Aktivität oder Gewohnheit hinzu."
          />
        ) : (
          <ActivityList
            activities={statusActivities}
            onToggle={handleToggle}
            onEdit={handleEdit}
            onDelete={handleDelete}
            categories={CATEGORIES}
            onAdd={addActivity}
            isFuture={isFuture}
          />
        )}
      </main>
    </div>
  );
}

