const fs = require('fs');
const zlib = require('zlib');

// Create a simple PNG icon with a pulse/heartbeat design
function createIcon(size) {
  // Raw pixel data: RGBA, 4 bytes per pixel
  const pixels = [];

  for (let y = 0; y < size; y++) {
    for (let x = 0; x < size; x++) {
      // Background: indigo #4F46E5 (79, 70, 229)
      let r = 79, g = 70, b = 229, a = 255;

      // Rounded corners (clip to rounded rect)
      const cornerRadius = size * 0.17;
      const dx = Math.min(x, size - 1 - x);
      const dy = Math.min(y, size - 1 - y);
      if (dx < cornerRadius && dy < cornerRadius) {
        const cornerX = (x < size / 2) ? cornerRadius : size - cornerRadius;
        const cornerY = (y < size / 2) ? cornerRadius : size - cornerRadius;
        const dist = Math.sqrt((x - cornerX) ** 2 + (y - cornerY) ** 2);
        if (dist > cornerRadius) {
          a = 0; // transparent outside rounded corners
        }
      }

      // Draw pulse line (white)
      if (a > 0) {
        const lineThickness = Math.max(2, Math.round(size / 24));
        const cx = x - size / 2;
        const cy = y - size / 2;

        // Horizontal line segments (the pulse waveform)
        const normX = x / size;
        const normY = y / size;

        // Draw the pulse shape
        let inLine = false;
        const wavePoints = [
          { x1: 0.25, y1: 0.5, x2: 0.35, y2: 0.5 },
          { x1: 0.35, y1: 0.5, x2: 0.40, y2: 0.30 },
          { x1: 0.40, y1: 0.30, x2: 0.47, y2: 0.75 },
          { x1: 0.47, y1: 0.75, x2: 0.53, y2: 0.25 },
          { x1: 0.53, y1: 0.25, x2: 0.60, y2: 0.55 },
          { x1: 0.60, y1: 0.55, x2: 0.70, y2: 0.55 },
          { x1: 0.70, y1: 0.55, x2: 0.75, y2: 0.50 },
          { x1: 0.75, y1: 0.50, x2: 0.85, y2: 0.50 },
        ];

        for (const wp of wavePoints) {
          const dx2 = wp.x2 - wp.x1;
          const dy2 = wp.y2 - wp.y1;
          const len = Math.sqrt(dx2 * dx2 + dy2 * dy2);

          for (let t = 0; t <= 1; t += 1 / (size * 2)) {
            const px = wp.x1 + dx2 * t;
            const py = wp.y1 + dy2 * t;
            const distToLine = Math.abs((py - wp.y1) * dx2 - (px - wp.x1) * dy2) / len;
            if (distToLine < lineThickness / size) {
              r = 255; g = 255; b = 255;
              inLine = true;
              break;
            }
          }
          if (inLine) break;
        }
      }

      pixels.push(r, g, b, a);
    }
  }

  // Create PNG using zlib
  const ihdr = Buffer.alloc(13);
  ihdr.writeUInt32BE(13, 0);
  ihdr.writeUInt32BE(size, 4);
  ihdr.writeUInt32BE(size, 8);
  ihdr[9] = 8; // bit depth
  ihdr[10] = 2; // RGB + alpha
  ihdr[11] = 0; // no compression
  ihdr[12] = 0; // no filter
  const idatData = Buffer.from(pixels);
  const compressed = zlib.deflateSync(idatData);
  const idat = Buffer.alloc(4 + compressed.length + 4);
  idat.writeUInt32BE(compressed.length, 0);
  compressed.copy(idat, 4);

  // CRC calculation
  const crc32 = (buf) => {
    let crc = -1;
    const table = [];
    for (let i = 0; i < 256; i++) {
      let c = i;
      for (let j = 0; j < 8; j++) c = (c & 1) ? (0xEDB88320 ^ (c >>> 1)) : (c >>> 1);
      table.push(c >>> 0);
    }
    for (let i = 0; i < buf.length; i++) crc = table[(crc ^ buf[i]) & 0xFF] ^ (crc >>> 8);
    return (crc ^ -1) >>> 0;
  };

  const createChunk = (type, data) => {
    const chunk = Buffer.alloc(4 + data.length + 4);
    chunk.writeUInt32BE(type.length, 0);
    chunk.set(type, 4);
    chunk.set(data, 4 + type.length);
    const crcVal = crc32(Buffer.concat([type, data]));
    chunk.writeUInt32BE(crcVal, 4 + type.length + 4);
    return chunk;
  };

  const signature = Buffer.from([0x89, 0x50, 0x4E, 0x47, 0x0D, 0x0A, 0x1A, 0x0A]);
  const chunks = [
    signature,
    createChunk(Buffer.from('IHDR'), ihdr),
    createChunk(Buffer.from('IDAT'), idat),
    createChunk(Buffer.from('IEND'), Buffer.alloc(0)),
  ];
  return Buffer.concat(chunks);
}

