// CRC32 lookup table
const crcTable = [];
for (let i = 0; i < 256; i++) {
  let c = i;
  for (let j = 0; j < 8; j++) {
    c = (c & 1) ? (0xEDB88320 ^ (c >>> 1)) : (c >>> 1);
  }
  crcTable.push(c >>> 0);
}

function crc32(buf) {
  let crc = -1;
  for (let i = 0; i < buf.length; i++) {
    crc = crcTable[(crc ^ buf[i]) & 0xFF] ^ (crc >>> 8);
  }
  return (crc ^ -1) >>> 0;
}

function createChunk(name, data) {
  const header = Buffer.alloc(8);
  header.writeUInt32BE(name.length, 0);
  header.writeUInt32BE(name.getByteLength ? name.getByteLength() : 0, 0);
  header[name.getByteLength ? 'write' : 'write']('IHDR', 0);
  // Actually let's just use Buffer.from
  const type = Buffer.from(name);
  const chunk = Buffer.alloc(4 + data.length + 4);
  type.copy(chunk, 0);
  data.copy(chunk, 4);
  const crcVal = crc32(Buffer.concat([type, data]));
  chunk.writeUInt32BE(crcVal, 4 + data.length);
  return chunk;
}

function createPNG(width, drawFn) {
  const pixels = [];

  for (let y = 0; y < width; y++) {
    for (let x = 0; x < width; x++) {
      let r = 79, g = 70, b = 229, a = 255;

      // Clip to rounded rect
      const cornerRadius = Math.round(width * 0.17);
      const dx = Math.min(x, width - 1 - x);
      const dy = Math.min(y, width - 1 - y);
      if (dx < cornerRadius && dy < cornerRadius) {
        const cornerX = (x < width / 2) ? cornerRadius : width - cornerRadius;
        const cornerY = (y < width / 2) ? cornerRadius : width - cornerRadius;
        const dist = Math.sqrt((x - cornerX) ** 2 + (y - cornerY) ** 2);
        if (dist > cornerRadius) {
          a = 0;
        }
      }

      // Draw pulse line
      if (a > 0) {
        const lineThick = Math.max(1, Math.round(width / 48));
        const wavePoints = [
          { x1: 0.25, y1: 0.5, x2: 0.35, y2: 0.5 },
          { x1: 0.35, y1: 0.5, x2: 0.42, y2: 0.28 },
          { x1: 0.42, y1: 0.28, x2: 0.47, y2: 0.72 },
          { x1: 0.47, y1: 0.72, x2: 0.53, y2: 0.28 },
          { x1: 0.53, y1: 0.28, x2: 0.60, y2: 0.55 },
          { x1: 0.60, y1: 0.55, x2: 0.70, y2: 0.55 },
          { x1: 0.70, y1: 0.55, x2: 0.78, y2: 0.48 },
          { x1: 0.78, y1: 0.48, x2: 0.88, y2: 0.48 },
        ];

        for (const wp of wavePoints) {
          const dx2 = wp.x2 - wp.x1;
          const dy2 = wp.y2 - wp.y1;
          const len = Math.sqrt(dx2 * dx2 + dy2 * dy2);
          const step = 1 / (width * 2);

          for (let t = 0; t <= 1; t += step) {
            const px = wp.x1 + dx2 * t;
            const py = wp.y1 + dy2 * t;
            const dist = Math.abs((py - wp.y1) * dx2 - (px - wp.x1) * dy2) / len;
            if (dist < (lineThick + 2) / width) {
              r = 255; g = 255; b = 255;
              break;
            }
          }
        }
      }

      pixels.push(r, g, b, a);
    }
  }

  const idat = zlib.deflateSync(Buffer.from(pixels));

  // PNG signature
  const signature = Buffer.from([0x89, 0x50, 0x4E, 0x47, 0x0D, 0x0A, 0x1A, 0x0A]);

  // IHDR
  const ihdr = Buffer.alloc(13);
  ihdr.writeUInt32BE(13, 0);
  ihdr.writeUInt32BE(width, 4);
  ihdr.writeUInt32BE(width, 8);
  ihdr[9] = 8;
  ihdr[10] = 6; // RGBA
  ihdr[11] = 0;
  ihdr[12] = 0;

  // IDAT
  const idatHeader = Buffer.alloc(4 + idat.length + 4);
  idatHeader.writeUInt32BE(idat.length, 0);
  idat.copy(idatHeader, 4);
  idatHeader.writeUInt32BE(crc32(Buffer.concat([Buffer.from('IDAT'), idat])), 4 + idat.length);

  // IEND
  const iendHeader = Buffer.alloc(4);
  iendHeader.writeUInt32BE(0, 0);
  iendHeader.writeUInt32BE(crc32(Buffer.from('IEND')), 4);

  const ihdrChunk = Buffer.alloc(4 + 13 + 4);
  ihdrChunk.writeUInt32BE(13, 0);
  Buffer.from('IHDR').copy(ihdrChunk, 4);
  ihdr.copy(ihdrChunk, 8);
  ihdrChunk.writeUInt32BE(crc32(Buffer.concat([Buffer.from('IHDR'), ihdr])), 8 + 13);

  return Buffer.concat([signature, ihdrChunk, idatHeader, iendHeader]);
}

